CREATE TABLE custom_field_definitions (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), entity_type text NOT NULL CHECK (entity_type IN ('contact','company','deal')), key text NOT NULL, label text NOT NULL, type text NOT NULL CHECK (type IN ('text','number','date','boolean','single_select','multi_select')), required boolean NOT NULL DEFAULT false, options jsonb NOT NULL DEFAULT '[]'::jsonb, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz);
CREATE UNIQUE INDEX custom_fields_org_entity_key_uidx ON custom_field_definitions (org_id, entity_type, key); CREATE INDEX custom_fields_org_entity_idx ON custom_field_definitions (org_id, entity_type); ALTER TABLE custom_field_definitions ENABLE ROW LEVEL SECURITY; CREATE POLICY custom_fields_isolation_by_org ON custom_field_definitions FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON custom_field_definitions TO app_user; ALTER PUBLICATION electric_publication_default ADD TABLE custom_field_definitions;
UPDATE permission_groups SET capabilities = capabilities || '["settings:manage"]'::jsonb, updated_at = now() WHERE name IN ('Proprietário','Administrador') AND NOT capabilities @> '["settings:manage"]'::jsonb;
